        "code": "#include <iostream>\n#include <stack>\n#include <string>\n\nbool isBalanced(const std::string& s) {\n    std::stack<char> st;\n    for (char ch : s) {\n        if (ch == '(' || ch == '[' || ch == '{') {\n            st.push(ch);   // opening bracket: remember it\n        } else {\n            if (st.empty()) return false;   // closing with no opener\n            char top = st.top();\n            st.pop();\n            // top must match this closing bracket\n            if ((ch == ')' && top != '(') ||\n                (ch == ']' && top != '[') ||\n                (ch == '}' && top != '{')) {\n                return false;\n            }\n        }\n    }\n    return st.empty();   // balanced only if nothing is left open\n}\n\nint main() {\n    std::cout << \"{[()]} balanced? \" << isBalanced(\"{[()]}\") << \"\\n\";\n    std::cout << \"{[(])} balanced? \" << isBalanced(\"{[(])}\") << \"\\n\";\n    std::cout << \"(( balanced? \" << isBalanced(\"((\") << \"\\n\";\n    return 0;\n}",
